import{_ as e,o as a,c as o,a3 as r}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"What is a Flow","description":"Automated processes in ApptiveGrid — built from a trigger, actions, and helpers.","frontmatter":{"title":"What is a Flow","description":"Automated processes in ApptiveGrid — built from a trigger, actions, and helpers."},"headers":[],"relativePath":"en/flows/was-ist-ein-flow.md","filePath":"en/flows/was-ist-ein-flow.md","lastUpdated":1787319236000}'),n={name:"en/flows/was-ist-ein-flow.md"};function s(i,t,l,h,d,p){return a(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="what-is-a-flow" tabindex="-1">What is a Flow <a class="header-anchor" href="#what-is-a-flow" aria-label="Permalink to &quot;What is a Flow&quot;">​</a></h1><p>A <strong>Flow</strong> is an automated process. It reacts to an event and then runs through a series of steps — without anyone having to step in.</p><p>The empty state in the Flows area sums it up: <em>Automate your work.</em></p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><p>Every Flow is made up of <strong>steps</strong>, chained together by connections. There are three kinds, grouped that way in the editor too:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Tab</th><th>Role</th></tr></thead><tbody><tr><td><strong>Trigger</strong></td><td><em>Trigger</em></td><td>The event that starts the Flow</td></tr><tr><td><strong>Actions</strong></td><td><em>Actions</em></td><td>What the Flow does</td></tr><tr><td><strong>Helpers</strong></td><td><em>Helpers</em></td><td>Control the flow of execution: branch, repeat, wait</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Exactly one trigger per Flow</p><p>A Flow always has exactly one trigger. If one is already set, the editor reports <em>This Flow already has a trigger</em> and jumps straight to the <em>Actions</em> tab when you try to add another.</p><p>If the same process needs to react to multiple events, you need multiple Flows.</p></div><h2 id="a-simple-example" tabindex="-1">A simple example <a class="header-anchor" href="#a-simple-example" aria-label="Permalink to &quot;A simple example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trigger: Entry via form</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Action:  Email  →  Confirmation to the person who signed up</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Action:  Update entry  →  Set status to &quot;Confirmed&quot;</span></span></code></pre></div><p>As soon as someone submits the sign-up form, the Flow runs: confirmation email goes out, status gets set in the Grid. Done.</p><h2 id="what-can-trigger-a-flow" tabindex="-1">What can trigger a Flow <a class="header-anchor" href="#what-can-trigger-a-flow" aria-label="Permalink to &quot;What can trigger a Flow&quot;">​</a></h2><p>Six triggers are available:</p><table tabindex="0"><thead><tr><th>Trigger</th><th>Starts when …</th></tr></thead><tbody><tr><td><strong>New entry</strong></td><td>an entry is created in a Grid</td></tr><tr><td><strong>Entry was changed</strong></td><td>an existing entry is changed</td></tr><tr><td><strong>Entry via form</strong></td><td>a form creates a new entry</td></tr><tr><td><strong>Entry changed via form</strong></td><td>a form changes an entry</td></tr><tr><td><strong>Webhook</strong></td><td>an outside system sends a request</td></tr><tr><td><strong>Show page</strong></td><td>a page is opened and submitted</td></tr></tbody></table><p>→ <a href="/en/flows/trigger">Trigger</a></p><h2 id="what-a-flow-can-do" tabindex="-1">What a Flow can do <a class="header-anchor" href="#what-a-flow-can-do" aria-label="Permalink to &quot;What a Flow can do&quot;">​</a></h2><p>Roughly four groups:</p><p><strong>Work with your own data</strong> — create entry, update entry, load all entries of a Grid</p><p><strong>Communicate outward</strong> — send email, send HTTP request, Slack, MS Teams, Firebase, HubSpot, SMS</p><p><strong>Generate files and content</strong> — QR code, PDF to text, URL to PDF, import CSV file, speech to text, calendar entry</p><p><strong>Interact with people</strong> — show page, create link to a page, prefilled form link</p><p>→ <a href="/en/flows/aktionen">Actions</a></p><h2 id="controlling-the-flow-of-execution" tabindex="-1">Controlling the flow of execution <a class="header-anchor" href="#controlling-the-flow-of-execution" aria-label="Permalink to &quot;Controlling the flow of execution&quot;">​</a></h2><p>Four helpers:</p><ul><li><strong>Router</strong> — <em>Take different paths</em>: branches the flow based on conditions</li><li><strong>Parallel</strong> — <em>Runs the following steps individually for each list element</em>: the loop over a list</li><li><strong>Merge runs</strong> — <em>Waits for all list runs and then continues the flow</em></li><li><strong>Wait</strong> — <em>Pauses the flow for a set duration</em></li></ul><p>→ <a href="/en/flows/router-und-parallel">Router and Parallel</a></p><h2 id="data-flows-from-step-to-step" tabindex="-1">Data flows from step to step <a class="header-anchor" href="#data-flows-from-step-to-step" aria-label="Permalink to &quot;Data flows from step to step&quot;">​</a></h2><p>Every step can access the results of the previous ones. In the step editor, the hint <em>Use values from previous steps</em> leads to the selection.</p><p>That&#39;s the basic principle: the trigger delivers an entry, the first action works with it, the second uses its result, and so on.</p><p>→ <a href="/en/flows/daten-zwischen-schritten">Data between steps</a></p><h2 id="flow-and-run" tabindex="-1">Flow and run <a class="header-anchor" href="#flow-and-run" aria-label="Permalink to &quot;Flow and run&quot;">​</a></h2><p>Two terms that are easy to mix up:</p><ul><li>The <strong>Flow</strong> is the blueprint — what you edit in the editor.</li><li>A <strong>run</strong> is a single execution. The interface calls this <em>Previous executions</em>.</li></ul><p>Every run has its own status (<em>Done</em>, <em>Error</em>, <em>Waiting</em>), a duration, and a count of executed steps.</p><p>→ <a href="/en/flows/durchlaufhistorie">Run history</a></p><h2 id="where-flows-live" tabindex="-1">Where Flows live <a class="header-anchor" href="#where-flows-live" aria-label="Permalink to &quot;Where Flows live&quot;">​</a></h2><p>Flows belong to a <strong>Space</strong>, not to a single Grid — even if their trigger refers to a Grid. You&#39;ll find them in the sidebar under <strong>Flows</strong>.</p><p>The editor has two tabs: <strong>Editor</strong> for building and <strong>History</strong> for past runs.</p><div class="warning custom-block"><p class="custom-block-title">Number of Flows depends on your plan</p><p>How many Flows a Space may contain depends on your plan. Some particularly powerful steps are also reserved for the top plan and marked <strong>Pro</strong> in the editor.</p></div><h2 id="switching-on-and-off" tabindex="-1">Switching on and off <a class="header-anchor" href="#switching-on-and-off" aria-label="Permalink to &quot;Switching on and off&quot;">​</a></h2><p>Every Flow has a <strong>switch</strong>. When it&#39;s set to <em>off</em>, the Flow and all its steps remain intact, but it no longer reacts to any event.</p><p>You&#39;ll find it in two places:</p><ul><li>in the list under <strong>Flows</strong>, to the right of each entry</li><li>inside the Flow itself, to the right of the <em>Editor</em> and <em>History</em> tabs</li></ul><p>A newly created Flow is switched on.</p><div class="tip custom-block"><p class="custom-block-title">Switching off is the gentle brake</p><p>Before a large <a href="/en/grids/csv-import">CSV import</a> or when cleaning up a <a href="/en/ansichten/kanban">Kanban board</a>, you don&#39;t need to rebuild the trigger — just switch the affected Flow off briefly and back on afterward.</p><p>Also useful while rebuilding a live Flow: as long as it&#39;s off, no half-finished configuration runs against real data.</p></div><div class="warning custom-block"><p class="custom-block-title">Switching off also halts runs in progress</p><p>Runs that are currently in progress or waiting for page input are not resumed after switching off. They stay wherever they were.</p></div><p>Only people with the <strong>Manage</strong> role and the owner may operate the switch. With <strong>Edit</strong> and <strong>View</strong>, it&#39;s visible but not operable.</p><p>ApptiveGrid also switches a Flow off automatically if it fails on the same error three times in a row → <a href="/en/flows/durchlaufhistorie#error-notifications">Run history</a></p><h2 id="when-a-flow-is-the-right-tool" tabindex="-1">When a Flow is the right tool <a class="header-anchor" href="#when-a-flow-is-the-right-tool" aria-label="Permalink to &quot;When a Flow is the right tool&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Better suited</th></tr></thead><tbody><tr><td>Send a confirmation after every sign-up</td><td><strong>Flow</strong></td></tr><tr><td>Show a value from a linked entry</td><td>Column type <a href="/en/referenz/spaltentypen">Use linked value</a></td></tr><tr><td>Sum up linked entries</td><td>Column type <a href="/en/referenz/spaltentypen">Calculate sum</a></td></tr><tr><td>Show only certain entries</td><td><a href="/en/ansichten/filtern-sortieren-gruppieren">Filter in a view</a></td></tr><tr><td>Report data to another system</td><td><strong>Flow</strong> or <a href="/en/integrationen/webhooks">Webhook</a></td></tr><tr><td>Model a multi-stage approval process</td><td><strong>Flow</strong> with <em>Show page</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Calculation is not a Flow</p><p>For derived values within an entry, calculated column types are almost always the better choice: they update instantly, don&#39;t consume a Flow, and can&#39;t be interrupted by an error.</p><p>A Flow is worth it when something should <strong>happen</strong> — not when something should merely be <strong>displayed</strong>.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/flows/ersten-flow-bauen">Building your first Flow</a></li><li><a href="/en/referenz/flow-schritte">Flow steps</a> — all steps at a glance</li><li><a href="/en/flows/trigger">Trigger</a></li><li><a href="/en/flows/aktionen">Actions</a></li><li><a href="/en/flows/testen">Testing Flows</a></li></ul>`,52)])])}const g=e(n,[["render",s]]);export{u as __pageData,g as default};
